import React from 'react';
import { Box, Tooltip, Typography } from '@mui/material';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import { getGlossaryTerm } from '../../constants/glossaryTerms';

export interface PlainLanguageLabelProps {
  termId: string;
  children?: React.ReactNode;
  /** inline: dotted underline with small icon; heading: label with trailing icon */
  variant?: 'inline' | 'heading';
}

const PlainLanguageLabel: React.FC<PlainLanguageLabelProps> = ({
  termId,
  children,
  variant = 'inline',
}) => {
  const entry = getGlossaryTerm(termId);
  const label = children ?? entry?.term ?? termId;

  if (!entry) {
    return <>{label}</>;
  }

  const tooltipContent = (
    <Typography variant="body2" sx={{ maxWidth: 300 }}>
      <strong>{entry.term}:</strong> {entry.plain}
    </Typography>
  );

  if (variant === 'heading') {
    return (
      <Box component="span" sx={{ display: 'inline-flex', alignItems: 'center', gap: 0.5 }}>
        <Typography component="span" variant="inherit" sx={{ fontWeight: 'inherit' }}>
          {label}
        </Typography>
        <Tooltip title={tooltipContent} arrow describeChild>
          <HelpOutlineIcon
            fontSize="small"
            aria-label={`What is ${entry.term}?`}
            sx={{ color: 'text.secondary', cursor: 'help', fontSize: 16 }}
          />
        </Tooltip>
      </Box>
    );
  }

  return (
    <Tooltip title={tooltipContent} arrow describeChild>
      <Box
        component="span"
        role="button"
        tabIndex={0}
        aria-label={`${label}. Tap for plain-language explanation.`}
        sx={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: 0.25,
          borderBottom: '1px dotted',
          borderColor: 'text.disabled',
          cursor: 'help',
        }}
      >
        {label}
        <HelpOutlineIcon sx={{ fontSize: 14, color: 'text.secondary' }} aria-hidden />
      </Box>
    </Tooltip>
  );
};

export default PlainLanguageLabel;
