import type { PrioritizedReadinessAction } from '../components/compliance/ComplianceReadinessActionQueue';
import type { ModuleGapBundle } from '../components/compliance/ComplianceReadinessGapPanel';
import { DOCUMENT_UPLOAD_PATH } from '../constants/documentRoutes';
import {
  estimatedScoreImpactForRemediation,
  remediationActionLabelForBlockedReason,
  remediationLinkForBlockedReason,
  remediationWarningTypeForBlockedReason,
} from '../constants/reportingUxLabels';

export type MsmeReadinessStep = {
  id: string;
  stepNumber: number;
  title: string;
  detail?: string | null;
  hubLink: string;
  ctaLabel: string;
  expectedScoreImpact?: number | null;
  framework?: string;
  warningType?: string;
  completed?: boolean;
};

const MSME_STEP_TITLE_OVERRIDES: Array<{ pattern: RegExp; title: string; ctaLabel: string }> = [
  {
    pattern: /upload|meter|kwh|litre|liter|bill|electricity|fuel|utility/i,
    title: 'Upload utility and fuel bills with meter readings',
    ctaLabel: 'Upload bills',
  },
  {
    pattern: /tier\s*1|spend-proxy|spend proxy|zoho|tally|accounting|activity/i,
    title: 'Replace ₹-only estimates with metered activity data',
    ctaLabel: 'Improve data quality',
  },
  {
    pattern: /assessment|baseline|footprint|carbon assessment/i,
    title: 'Run your carbon assessment for the reporting period',
    ctaLabel: 'Start assessment',
  },
  {
    pattern: /scope\s*3|residual|category/i,
    title: 'Classify purchases and logistics into emission categories',
    ctaLabel: 'Add category data',
  },
  {
    pattern: /boundary|organizational|operational|iso|assurance|base year|methodology/i,
    title: 'Complete ISO inventory setup (boundaries and base year)',
    ctaLabel: 'Complete ISO setup',
  },
  {
    pattern: /brsr|principle|section|turnover|employee|registration|mandatory/i,
    title: 'Fill in company details required for BRSR disclosure',
    ctaLabel: 'Complete BRSR fields',
  },
  {
    pattern: /cbam|export|installation|shipment|registry/i,
    title: 'Add EU export and installation data for CBAM',
    ctaLabel: 'Open export setup',
  },
  {
    pattern: /production|pat|sec|gps|facility/i,
    title: 'Add production output and facility evidence',
    ctaLabel: 'Add production data',
  },
];

const simplifyMsmeStepTitle = (raw: string, hubLink?: string | null): { title: string; ctaLabel: string } => {
  const text = raw.trim();
  const matched = MSME_STEP_TITLE_OVERRIDES.find((entry) => entry.pattern.test(text));
  if (matched) {
    return { title: matched.title, ctaLabel: matched.ctaLabel };
  }
  if (hubLink === DOCUMENT_UPLOAD_PATH) {
    return { title: 'Upload supporting bills and invoices', ctaLabel: 'Upload bills' };
  }
  if (hubLink?.includes('start-assessment')) {
    return { title: 'Run your carbon assessment', ctaLabel: 'Start assessment' };
  }
  return {
    title: text.length > 90 ? `${text.slice(0, 87)}…` : text,
    ctaLabel: remediationActionLabelForBlockedReason(text),
  };
};

const stepDedupeKey = (step: { title: string; hubLink: string }) => {
  const normalizedLink = step.hubLink.split('?')[0];
  if (normalizedLink === DOCUMENT_UPLOAD_PATH || normalizedLink.includes('start-assessment')) {
    return normalizedLink;
  }
  return `${step.hubLink}|${step.title.toLowerCase().slice(0, 48)}`;
};

const DEFAULT_LOW_SCORE_STEPS: Array<Omit<MsmeReadinessStep, 'stepNumber'>> = [
  {
    id: 'default-assessment',
    title: 'Run your carbon assessment for the reporting period',
    detail: 'Sets your reporting period and total emissions baseline.',
    hubLink: '/carbon-footprint?section=start-assessment',
    ctaLabel: 'Start assessment',
    expectedScoreImpact: 15,
    framework: 'BRSR',
    warningType: 'readiness_blocked',
  },
  {
    id: 'default-upload-bills',
    title: 'Upload electricity and fuel bills with kWh or litres',
    detail: 'Metered bills raise data quality and readiness scores faster than accounting imports alone.',
    hubLink: DOCUMENT_UPLOAD_PATH,
    ctaLabel: 'Upload bills',
    expectedScoreImpact: 12,
    framework: 'ISO14064',
    warningType: 'spend_proxy_heavy',
  },
  {
    id: 'default-recheck',
    title: 'Re-check readiness after uploading data',
    detail: 'We will refresh your score and unlock filing-ready exports when gates pass.',
    hubLink: '/compliance',
    ctaLabel: 'Check readiness',
    expectedScoreImpact: null,
    framework: 'ADVISORY',
    warningType: 'readiness_blocked',
  },
];

export const buildMsmeReadinessSteps = ({
  prioritizedActions = [],
  moduleGapDetails = {},
  moduleKeys = [],
  overallReadinessScore = null,
  maxSteps = 3,
}: {
  prioritizedActions?: PrioritizedReadinessAction[];
  moduleGapDetails?: Record<string, ModuleGapBundle>;
  moduleKeys?: string[];
  overallReadinessScore?: number | null;
  maxSteps?: number;
}): MsmeReadinessStep[] => {
  const seen = new Set<string>();
  const candidates: Omit<MsmeReadinessStep, 'stepNumber'>[] = [];

  const pushCandidate = (step: Omit<MsmeReadinessStep, 'stepNumber'>) => {
    const key = stepDedupeKey(step);
    if (seen.has(key) || step.completed) {
      return;
    }
    seen.add(key);
    candidates.push(step);
  };

  prioritizedActions.forEach((action) => {
    const hubLink = action.hubLink || remediationLinkForBlockedReason(action.action) || '/compliance';
    const simplified = simplifyMsmeStepTitle(action.action, hubLink);
    pushCandidate({
      id: action.id,
      title: simplified.title,
      detail: action.detail,
      hubLink,
      ctaLabel: simplified.ctaLabel,
      expectedScoreImpact: action.expectedScoreImpact
        ?? estimatedScoreImpactForRemediation(action.action),
      framework: action.framework,
      warningType: remediationWarningTypeForBlockedReason(action.action),
    });
  });

  moduleKeys.forEach((moduleKey) => {
    const bundle = moduleGapDetails[moduleKey];
    if (!bundle?.gaps?.length) {
      return;
    }
    bundle.gaps.forEach((gap) => {
      const hubLink = gap.hubLink || bundle.hubLink || remediationLinkForBlockedReason(gap.label) || '/compliance';
      const simplified = simplifyMsmeStepTitle(gap.label, hubLink);
      pushCandidate({
        id: `${moduleKey}:${gap.id}`,
        title: simplified.title,
        detail: gap.detail,
        hubLink,
        ctaLabel: gap.dataFeedSatisfied ? 'Review data' : simplified.ctaLabel,
        expectedScoreImpact: estimatedScoreImpactForRemediation(gap.label),
        framework: moduleKey,
        warningType: remediationWarningTypeForBlockedReason(gap.label),
        completed: gap.dataFeedSatisfied,
      });
    });
  });

  if (candidates.length < maxSteps && (overallReadinessScore == null || overallReadinessScore < 75)) {
    DEFAULT_LOW_SCORE_STEPS.forEach((step) => {
      if (candidates.length >= maxSteps) {
        return;
      }
      if (seen.has(stepDedupeKey(step))) {
        return;
      }
      pushCandidate(step);
    });
  }

  return candidates.slice(0, maxSteps).map((step, index) => ({
    ...step,
    stepNumber: index + 1,
  }));
};
